from __future__ import annotations

import reflex as rx

from . import agent_common as ac
from .common import switcher


def _node(x: int, y: int, w: int, mode: str, title: rx.Component | str, *body: rx.Component) -> rx.Component:
    return rx.el.div(
        rx.el.div(title, class_name="node-head sans"),
        rx.el.div(*body, class_name="node-body"),
        class_name=f"node m-{mode}",
        style={"left": f"{x}px", "top": f"{y}px", "width": f"{w}px"},
    )


def _wire(x: int, y: int, w: int, h: int, kind: str = "h") -> rx.Component:
    """Straight or elbow connector drawn with borders; kind is h, v, or an elbow (down-right / right-down)."""
    return rx.el.div(
        class_name=f"wire wire-{kind}", style={"left": f"{x}px", "top": f"{y}px", "width": f"{w}px", "height": f"{h}px"}
    )


def _r1_preview() -> rx.Component:
    return rx.el.table(
        rx.el.thead(rx.el.tr(*[rx.el.th(name) for name, _ in ac.COLUMNS[:1] + ac.COLUMNS[-2:]])),
        rx.el.tbody(*[rx.el.tr(rx.el.td(r[0]), rx.el.td(r[-2]), rx.el.td(r[-1])) for r in ac.ROWS[:5]]),
        class_name="df mono",
    )


